package ttviet.dao; import java.sql.*; public class AuthDAO { public static boolean login(String u,String p){String q="SELECT id FROM users WHERE username=? AND password=?";try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setString(1,u);s.setString(2,p);try(ResultSet r=s.executeQuery()){return r.next();}}catch(SQLException e){javax.swing.JOptionPane.showMessageDialog(null,"Lỗi MySQL: "+e.getMessage());return false;}} }